<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { api, apiWithVersion, localDate } from './api';
import ContentEditor from './components/ContentEditor.vue';
import DraftMappingPreview from './components/DraftMappingPreview.vue';
import PaperReview from './components/PaperReview.vue';
import GoalEditor from './components/GoalEditor.vue';
import FamilySettings from './components/FamilySettings.vue';
import KnowledgeChanges from './components/KnowledgeChanges.vue';
import OperationalStatus from './components/OperationalStatus.vue';
import BuilderRuns from './components/BuilderRuns.vue';
import MappingWorkbench from './components/MappingWorkbench.vue';
import ContentReviewHistory from './components/ContentReviewHistory.vue';
import PublishedMappingView from './components/PublishedMappingView.vue';
const mappingReleaseId=ref(''),coverageDraftId=ref(''),draftVersion=ref('');
const reviewDraftId=ref(''),reviewHistoryVersion=ref(0),reviewNotes=ref<Record<string,string>>({});
import ParentBurden from './components/ParentBurden.vue';
import WeeklyOverview from './components/WeeklyOverview.vue';
type Item = Record<string, any>;
const deletionReceipt=ref<Item|null>(null);try{deletionReceipt.value=JSON.parse(sessionStorage.getItem('family-deletion-receipt')||'null')}catch{sessionStorage.removeItem('family-deletion-receipt')}
function closeReceipt(){deletionReceipt.value=null;sessionStorage.removeItem('family-deletion-receipt')}
function downloadReceipt(){const url=URL.createObjectURL(new Blob([JSON.stringify(deletionReceipt.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='family-deletion-receipt.json';a.click();URL.revokeObjectURL(url);}
const me = ref<Item|null>(null), students = ref<Item[]>([]), studentId = ref(''), page = ref('today');
const evidencePending=ref(0);let projectionTimer:number|undefined;let projectionDeadline=0;
function scheduleEvidenceRefresh(id:string){if(Date.now()>=projectionDeadline)return;projectionTimer=window.setTimeout(()=>{if(page.value==='assessment'&&studentId.value===id&&me.value&&can('Parent')){if(busy.value)scheduleEvidenceRefresh(id);else run(()=>refresh(true));}},750)}
const busy = ref(false), error = ref(''), notice = ref(''), offline = ref(!navigator.onLine);
const credentials = ref({ userName: '', password: '', familyName: '我的家庭' }), registering = ref(false);
const newStudent = ref({ name: '', grade: 3, dailyMinutes: 30, timeZone: 'Asia/Shanghai' });
const view = ref<Item>({ tasks: [] }), catalog = ref<Item|null>(null), content = ref<Item>({drafts:[],releases:[]});
const date = ref(localDate()), lessonId = ref(''), budget = ref(30), reserved = ref(0);
const goals=ref<Item[]>([]), schoolProgress=ref<Item[]>([]), progressChanges=ref<Item[]>([]), correctionProgressId=ref(''), progressReason=ref('');
const manual = ref({ title: '学校作业', minutes: 15, resourceRef: '完成学校布置的纸质作业', type: 'Schoolwork', mandatory: true, questionId: null as string|null });
const planAdjustmentReason=ref(''),planVersion=ref('');
watch(()=>view.value.revision?.id,()=>{planAdjustmentReason.value='';});
const manualQuestions=ref<Item[]>([]), gradingContext=ref<Item|null>(null), gradingForm=ref<Item>({result:"Correct",reason:"",steps:[]});
const reportEnd=ref('');
const masteries = ref<Item[]>([]), reviews = ref<Item[]>([]), attempts = ref<Item>({attempts:[],gradings:[]}), summary = ref<Item|null>(null), detail = ref<Item|null>(null);
const builder = ref<Item>({sources:[],runs:[],candidates:[],chunks:[]}), source = ref({ title: '', text: '', allowExternalAI: false, usageScope: 'FamilyOnly' });
const paper = ref({stem:'',answer:'',fileId:null as string|null,errorType:'Unknown'}), paperWrongs=ref<Item[]>([]), deletePreview=ref<Item|null>(null), deletePassword=ref(''), deleteConfirm=ref('');
const gradingPreview=ref<Item|null>(null), mappingPreview=ref<Item|null>(null), mappingRelease=ref(''), mappingAttempt=ref(''), deferTask=ref<Item|null>(null), deferDate=ref(localDate()), deferReason=ref('');
const selectedTask = ref<Item|null>(null), session = ref<Item|null>(null), answer = ref(''), feedback = ref<Item|null>(null), hint = ref(''), submissionKey = ref('');
const provenance=ref<Item|null>(null),reviewingPaper=ref<Item|null>(null);
const draftId = ref(''), draftTitle = ref(''), editingCatalog = ref<Item|null>(null);
const publishedKCIds=computed(()=>[...new Set<string>(content.value.releases.flatMap((r:Item)=>JSON.parse(r.payload).kcs.map((k:Item)=>k.id)))]);
const student = computed(()=>students.value.find(s=>s.id===studentId.value));
function can(role:string){const roles=(me.value?.actor.roles||'').split(',');return me.value?.actor.role!=='Child'&&(roles.includes(role)||(role==='ContentEditor'&&roles.includes('Publisher')));}
const isChild = computed(()=>me.value?.actor.role==='Child');
const activeTask = computed(()=>view.value.tasks?.find((t:Item)=>t.status==='InProgress') || view.value.tasks?.find((t:Item)=>t.status==='Ready'));
const awaitingGrade = computed(()=>!!session.value && !session.value.canComplete && feedback.value?.grading?.result==='Pending');
const canFinish = computed(()=>!session.value || session.value.canComplete || (!!feedback.value?.grading?.result && feedback.value.grading.result!=='Pending'));
const completed = computed(()=>view.value.tasks?.filter((t:Item)=>t.status==='Completed').length || 0);
const status: Record<string,string> = { Planned:'待发布', Ready:'准备开始', InProgress:'进行中', Completed:'已完成', Skipped:'已跳过', Deferred:'已延期', Abandoned:'已结束', Unknown:'证据不足',Learning:'学习中',CanDo:'近期会做',Mastered:'已掌握',Stable:'保持稳定',Pending:'待确认',Correct:'正确',Incorrect:'错误',Partial:'部分正确',Unscorable:'不可评分',Draft:'草稿',Approved:'审核通过',Published:'已发布',Accepted:'已接受',Rejected:'已拒绝',Queued:'排队中' };
async function run(action:()=>Promise<void>) { if(busy.value)return; busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=(e as Error).message}finally{busy.value=false} }
async function loadIdentity(){ me.value=await api('/me');if(!isChild.value&&!can('Parent'))page.value='content';students.value=await api('/students');if(!students.value.some(s=>s.id===studentId.value))studentId.value=students.value[0]?.id || ''; if(student.value) {budget.value=student.value.dailyMinutes;date.value=localDate(student.value.timeZone);} }
async function refresh(auto=false){
  window.clearTimeout(projectionTimer);if(!auto)projectionDeadline=Date.now()+30000;
  if(!studentId.value && page.value!=='content' && page.value!=='builder')return;
  if(page.value==='today')view.value=await api(`/students/${studentId.value}/today`);
  if(page.value==='plan'){catalog.value=await api(`/students/${studentId.value}/catalog`);const planResponse=await apiWithVersion<Item>(`/students/${studentId.value}/plans/${date.value}`);view.value=planResponse.data;planVersion.value=planResponse.version;manualQuestions.value=view.value.revision?await api(`/plans/${view.value.revision.id}/questions`):[];const availability=await api(`/students/${studentId.value}/availability/${date.value}`);budget.value=availability.minutes;reserved.value=availability.reserved;goals.value=await api(`/students/${studentId.value}/goals`);schoolProgress.value=await api(`/students/${studentId.value}/progress`);progressChanges.value=await api(`/students/${studentId.value}/progress-changes`);if(!catalog.value?.lessons?.some((l:Item)=>l.id===lessonId.value))lessonId.value='';if(!lessonId.value)lessonId.value=schoolProgress.value.find(p=>catalog.value?.lessons?.some((l:Item)=>l.id===p.lessonId))?.lessonId || '';}
  if(page.value==='content')content.value=await api('/content');
  if(page.value==='builder')builder.value=await api('/builder');
  if(page.value==='assessment'){content.value=await api('/content');catalog.value=await api(`/students/${studentId.value}/catalog`);const m=await api(`/students/${studentId.value}/mastery`);masteries.value=m.masteries;evidencePending.value=m.pending;reviews.value=await api(`/students/${studentId.value}/reviews`);attempts.value=await api(`/students/${studentId.value}/attempts`);paperWrongs.value=await api(`/students/${studentId.value}/paper-wrongs`);if(evidencePending.value>0)scheduleEvidenceRefresh(studentId.value);}
  if(page.value==='report')summary.value=await api(`/students/${studentId.value}/weekly-summary${reportEnd.value?'?end='+reportEnd.value:''}`);
}
async function changeStudent(){await run(async()=>{reportEnd.value='';summary.value=null;planAdjustmentReason.value='';lessonId.value='';correctionProgressId.value='';progressReason.value='';schoolProgress.value=[];progressChanges.value=[];selectedTask.value=null;session.value=null;detail.value=null;provenance.value=null;gradingPreview.value=null;reviewingPaper.value=null;gradingContext.value=null;mappingPreview.value=null;mappingAttempt.value='';deletePreview.value=null;deletePassword.value='';deleteConfirm.value='';deferTask.value=null;paper.value={stem:'',answer:'',fileId:null,errorType:'Unknown'};date.value=localDate(student.value?.timeZone);budget.value=student.value?.dailyMinutes||30;await refresh();});}
function lessonName(id:string){return catalog.value?.lessons.find((l:Item)=>l.id===id)?.title || '原发布版本课时';}
function progressDescription(c:Item){const before=JSON.parse(c.before),after=JSON.parse(c.after);const target=after.replacement || (c.newProgressId===c.oldProgressId?after:null);return `${before.date} · ${lessonName(before.lessonId)} → ${target?lessonName(target.lessonId):'撤回'}`;}
async function correctProgress(lesson:string|null){await run(async()=>{await api(`/students/${studentId.value}/progress/${correctionProgressId.value}:correct`,{lessonId:lesson,reason:progressReason.value});correctionProgressId.value='';progressReason.value='';lessonId.value='';await refresh();notice.value='进度已纠正；生成新草稿时采用有效记录，历史学习记录保留。';});}
async function navigate(p:string){if(busy.value){await new Promise<void>(resolve=>{const timer=setInterval(()=>{if(!busy.value){clearInterval(timer);resolve()}},25)});}await run(async()=>{selectedTask.value=null;session.value=null;detail.value=null;provenance.value=null;reviewingPaper.value=null;gradingContext.value=null;gradingPreview.value=null;page.value=p;await refresh()});}
async function login(){await run(async()=>{await api(registering.value?'/auth/register':'/auth/login',credentials.value);credentials.value.password='';await loadIdentity();await refresh();});}
async function logout(){await run(async()=>{await api('/logout',{});window.clearTimeout(projectionTimer);evidencePending.value=0;me.value=null;students.value=[];studentId.value='';view.value={tasks:[]};session.value=null;selectedTask.value=null;credentials.value.password='';registering.value=false;provenance.value=null;lessonId.value='';catalog.value=null;content.value={drafts:[],releases:[]};masteries.value=[];reviews.value=[];detail.value=null;provenance.value=null;gradingPreview.value=null;reviewingPaper.value=null;gradingContext.value=null;mappingPreview.value=null;deletePreview.value=null;deletePassword.value='';deleteConfirm.value='';});}
async function createStudent(){await run(async()=>{const created=await api('/students',newStudent.value);studentId.value=created.id;lessonId.value='';await loadIdentity();page.value='content';await refresh();});}
async function publishContent(d:Item){if(draftId.value){error.value='请先保存或取消当前编辑，再审核发布。';return;}await run(async()=>{await api(`/content/drafts/${d.id}/reviews`,{expectedDraftVersion:d.version,reason:reviewNotes.value[d.id]||null});const preview=await api(`/content/drafts/${d.id}/preview`);await api(`/content/drafts/${d.id}:publish`,{previewHash:preview.hash});await refresh();if(reviewDraftId.value===d.id)reviewHistoryVersion.value++;notice.value='内容已发布，可以绑定学生。';});}
async function enterChild(){await run(async()=>{await api(`/students/${studentId.value}/child-sessions`,{});window.location.reload();});}
async function bindContent(id:string){await run(async()=>{await api(`/students/${studentId.value}/content/${id}:bind`,{});await loadIdentity();notice.value='已绑定；新计划将使用这个版本。';});}
async function generate(){await run(async()=>{await api(`/students/${studentId.value}/plans/${date.value}:generate`,{});await refresh();});}
async function publishPlan(){await run(async()=>{await api(`/plans/${view.value.revision.id}:publish`,{previewHash:view.value.revision.inputHash,confirmWarnings:true},'POST',undefined,planVersion.value);await refresh();notice.value='计划已发布，孩子可以开始。';});}
async function loadDraft(d:Item){const preview=await apiWithVersion(`/content/drafts/${d.id}/mapping-preview`);draftId.value=d.id;draftVersion.value=preview.version;draftTitle.value=preview.data.title;editingCatalog.value=preview.data.catalog;editingCatalog.value!.lessons.forEach((l:Item)=>{l.estimatedMinutes??=5;l.sourceRefs??=[];});}
async function editDraft(d:Item){await run(()=>loadDraft(d));}
async function cloneDraft(d:Item){await run(async()=>{const preview=await api(`/content/drafts/${d.id}/mapping-preview`);await api('/content/drafts',{title:d.title+' · 修订',catalog:preview.catalog});await refresh();});}
async function saveDraft(){await run(async()=>{const c=JSON.parse(JSON.stringify(editingCatalog.value));c.resources.forEach((r:Item)=>{r.url=r.url?.trim()||null;r.revisionId=crypto.randomUUID();});c.kcs.forEach((k:Item)=>k.revisionId=crypto.randomUUID());c.questions.forEach((q:Item)=>{q.revisionId=crypto.randomUUID();q.hint=q.hint?.trim()||null;});c.lessons.forEach((l:Item)=>l.revisionId=crypto.randomUUID());for(const list of [c.textbooks||[],c.units||[],c.courses||[]])list.forEach((x:Item)=>x.revisionId=crypto.randomUUID());await api(`/content/drafts/${draftId.value}`,{title:draftTitle.value,catalog:c},'PUT',undefined,draftVersion.value);await refresh();draftId.value='';notice.value='草稿已保存，需要重新审核。';});}
async function startTask(t:Item){await run(async()=>{selectedTask.value=t;feedback.value=null;hint.value='';answer.value='';session.value=null;submissionKey.value=crypto.randomUUID();if(t.status==='Ready'){await api(`/tasks/${t.id}:transition`,{status:'InProgress'});t.status='InProgress';}if(t.questionId){session.value=await api(`/tasks/${t.id}/sessions`,{});const saved=session.value!.lastAttempt;if(saved){answer.value=saved.answer;feedback.value={grading:{result:saved.result},feedback:saved.result==='Pending'?'已保存，等待家长确认':`已保存 · ${status[saved.result] || saved.result}`};}}await refresh();});}
async function submit(){await run(async()=>{if(!session.value)return;feedback.value=await api(`/sessions/${session.value.sessionId}/attempts`,{clientSubmissionId:submissionKey.value,answer:answer.value},'POST',submissionKey.value);submissionKey.value=crypto.randomUUID();});}
async function finish(){await run(async()=>{await api(`/tasks/${selectedTask.value!.id}:transition`,{status:'Completed'});selectedTask.value=null;session.value=null;await refresh();});}
async function takeHint(level:number){await run(async()=>{hint.value=(await api(`/sessions/${session.value!.sessionId}/hints`,{level})).text;session.value!.hintLevel=level;});}
async function openGrading(id:string){await run(async()=>{gradingPreview.value=null;gradingContext.value=await api(`/attempts/${id}/grading-context`);const c=gradingContext.value!;const previous=JSON.parse(c.grade.steps);gradingForm.value={result:c.grade.result==='Pending'?'Correct':c.grade.result,reason:'',steps:c.observations.map((o:Item)=>({...o,...(previous.find((p:Item)=>p.step===o.step)||{result:'Unknown',hintLevel:0})}))};});}
async function previewObservedGrade(){await run(async()=>{const id=gradingContext.value!.attempt.id;const input={result:gradingForm.value.result,reason:gradingForm.value.reason,steps:gradingForm.value.steps.map((s:Item)=>({step:s.step,result:s.result,hintLevel:s.hintLevel}))};gradingPreview.value={...await api(`/attempts/${id}/grading-preview`,input),attemptId:id,input};});}
async function appendManualTask(){await run(async()=>{await api(`/plans/${view.value.revision.id}/tasks`,{...manual.value,questionId:manual.value.type==='Practice'?manual.value.questionId:null});manual.value.questionId=null;await refresh();});}
async function previewMapping(){await run(async()=>{const input={releaseId:mappingRelease.value,attemptIds:[mappingAttempt.value],reason:'家长核对题目测量目标后更正'};mappingPreview.value={...await api(`/students/${studentId.value}/mapping-corrections:preview`,input),input};});}
async function confirmMapping(){await run(async()=>{const p=mappingPreview.value!;await api(`/students/${studentId.value}/mapping-corrections:confirm`,{...p.input,previewHash:p.previewHash});mappingPreview.value=null;await refresh();notice.value='映射更正已确认，后台将重放证据与日程。';});}
async function defer(){await run(async()=>{await api(`/tasks/${deferTask.value!.id}:defer`,{date:deferDate.value,reason:deferReason.value});deferTask.value=null;selectedTask.value=null;session.value=null;await refresh();notice.value='任务已顺延，请到目标日期确认并发布草稿。';});}
async function confirmGrade(){await run(async()=>{const p=gradingPreview.value!;await api(`/attempts/${p.attemptId}/grading-revisions`,{...p.input,previewHash:p.previewHash});gradingPreview.value=null;reviewingPaper.value=null;gradingContext.value=null;await refresh();notice.value='判分已保存，证据将重新计算。';});}
async function upload(event:Event,pdf:boolean){await run(async()=>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const saved=await api('/files',{name:file.name,mimeType:file.type,base64});if(pdf){await api('/content/pdf-sources',{fileId:saved.id,title:file.name,allowExternalAI:false,usageScope:'FamilyOnly'});await refresh();notice.value='PDF 已私有保存，正在后台解析；刷新查看结果。';}else{paper.value.fileId=saved.id;notice.value='图片已私有保存，可以登记纸质错题。';}});}
async function openCandidateDraft(c:Item){await navigate('content');const d=content.value.drafts.find((d:Item)=>d.id===c.createdDraftId);if(d?.status==='Published'){notice.value='这份草稿已发布；如需修改，请创建新修订。';}else if(d)await editDraft(d);else error.value='草稿不存在，请刷新后检查。';}
async function showProvenance(id:string){await run(async()=>{provenance.value=await api(`/content/kcs/${id}/provenance`);});}
async function decide(c:Item,decision:string){await run(async()=>{await api(`/builder/candidates/${c.id}:decide`,{decision,reason:'家长逐项审核来源与可测行为',name:c.name,behavior:c.behavior,boundary:c.boundary});await refresh();});}
async function changePlanTasks(t:Item,action:'up'|'down'|'lock'|'remove'){
  await run(async()=>{
    const reason=planAdjustmentReason.value.trim();if(!reason)throw new Error('请先填写本次计划调整原因。');
    let tasks:Item[]=view.value.tasks.map((item:Item)=>({...item}));const index=tasks.findIndex(item=>item.id===t.id);if(index<0)return;
    if(action==='remove'){
      if(t.mandatory||t.locked||['Completed','InProgress'].includes(t.status))throw new Error('已执行、必做或锁定任务不能移除；可选任务请先解除锁定。');
      tasks=tasks.filter(item=>item.id!==t.id);
    }else if(action==='lock')tasks[index].locked=!tasks[index].locked;
    else{const next=index+(action==='up'?-1:1);if(next<0||next>=tasks.length)return;[tasks[index],tasks[next]]=[tasks[next],tasks[index]];}
    await api(`/plans/${view.value.revision.id}:adjust`,{taskIds:tasks.map(item=>item.id),lockedIds:tasks.filter(item=>item.locked).map(item=>item.id),reason},'POST',undefined,planVersion.value);
    await refresh();planAdjustmentReason.value='';notice.value='调整已保存到草稿，发布后才应用到孩子的计划。';
  });
}

onMounted(()=>{window.addEventListener('online',()=>offline.value=false);window.addEventListener('offline',()=>offline.value=true);run(async()=>{try{await loadIdentity();await refresh();}catch(e){me.value=null;if(!(e as Error).message.includes('登录'))throw e;}});});
</script>

<template>
  <div class="app-shell">
    <aside v-if="me" class="sidebar">
      <a class="brand" href="#" @click.prevent="navigate(isChild||can('Parent')?'today':'content')"><span class="brand-mark">步</span><span>小步<small>家庭学习系统</small></span></a>
      <div class="family-label">{{ me.family.name }}</div>
      <nav aria-label="页面导航"><template v-if="isChild||can('Parent')"><button :class="{selected:page==='today'}" @click="navigate('today')">☀　今日学习</button></template><template v-if="can('Parent')"><button @click="navigate('plan')">▤　进度与计划</button><button @click="navigate('assessment')">◎　证据与复习</button><button @click="navigate('report')">▥　每周回顾</button></template><template v-if="!isChild"><div class="nav-label">内容工作台</div><button @click="navigate('content')">▧　内容与发布</button><button v-if="can('ContentEditor')" @click="navigate('builder')">✧　辅助建库</button><button v-if="can('Parent')" @click="navigate('settings')">⚙　家庭设置</button></template></nav>
      <div class="sidebar-foot"><span class="privacy-dot"></span>本地私有 · {{ isChild ? '孩子模式' : can('Parent') ? '家长模式' : '内容模式' }}<button class="text-button" @click="logout">{{isChild?'返回家长登录':'退出登录'}}</button></div>
    </aside>
    <main :class="{'login-main':!me}">
      <div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="notice" class="alert success" role="status">{{ notice }}</div><div v-if="offline" class="alert error">当前离线，无法提交或同步。恢复网络后再试。</div>
      <section v-if="!me&&deletionReceipt" class="card" aria-label="家庭删除回执"><h2>全家数据已删除</h2><p>回执编号：{{deletionReceipt.receiptId}}</p><button @click="downloadReceipt">下载删除回执</button><button @click="closeReceipt">关闭回执</button></section><div v-if="!me" class="login-card"><div class="brand-mark">步</div><p class="eyebrow">每天一小步</p><h1>让学习有迹可循。</h1><p class="muted">家长安排，孩子专注。把计划、作答与复习连接起来。</p><form @submit.prevent="login"><label>家长用户名<input v-model="credentials.userName" autocomplete="username" required minlength="3"></label><label>家长密码<input v-model="credentials.password" type="password" :autocomplete="registering?'new-password':'current-password'" required :minlength="registering?12:1"></label><label v-if="registering">家庭名称<input v-model="credentials.familyName"></label><button class="primary" :disabled="busy">{{registering?'创建私有家庭':'登录'}}</button></form><button class="text-button" @click="registering=!registering">{{registering?'已有账号？登录':'首次使用？创建家庭'}}</button></div>
      <template v-else>
        <header class="topbar"><span>{{ isChild ? '专注今天，慢慢进步' : '北师大版 · 三年级上册 · 混合运算' }}</span><div><select v-if="students.length" v-model="studentId" aria-label="切换学生" :disabled="busy" @change="changeStudent"><option v-for="s in students" :value="s.id">{{s.name}}</option></select><span class="date-chip">{{date}}</span></div></header>
        <OperationalStatus v-if="can('Parent')" :detailed="page==='settings'" @details="navigate('settings')" />
        <section v-if="can('Parent') && !students.length && !['content','builder','settings'].includes(page)" class="empty card"><h1>先认识一下小学习者</h1><p>创建学生，再准备内容和今日计划。</p><form class="form-grid" @submit.prevent="createStudent"><label>孩子昵称<input v-model="newStudent.name" required></label><label>年级<input v-model.number="newStudent.grade" type="number" min="1" max="12"></label><label>每天可用分钟<input v-model.number="newStudent.dailyMinutes" type="number" min="0" max="600"></label><button class="primary" :disabled="busy">创建学生</button></form></section>
        <template v-else-if="page==='today'">
          <div class="page-heading"><div><p class="eyebrow">TODAY / 今日学习</p><h1>{{student?.name}}，今天也向前一步</h1><p class="muted">一次专注一个任务，做完就去休息。</p></div><button v-if="!isChild" @click="enterChild" :disabled="busy">进入孩子模式 ↗</button></div>
          <div v-if="selectedTask" class="study-card card"><button class="text-button" @click="selectedTask=null;session=null">← 返回今日任务</button><div class="task-kind">{{ selectedTask.type==='Review'?'复习时间':selectedTask.questionId?'动笔试一试':'学习时间' }}</div><h2>{{selectedTask.title}}</h2><p class="muted">{{selectedTask.reason}}</p><template v-if="session"><p class="question-stem">{{session.stem}}</p><form @submit.prevent="submit"><label>你的答案<input v-model="answer" :inputmode="session.type==='Numeric'?'decimal':'text'" required autocomplete="off" autofocus></label><button class="primary" :disabled="busy||offline">{{busy?'正在保存…':'提交答案'}}</button></form><div class="hint-actions"><button @click="takeHint(1)" :disabled="busy">给我一点提示</button><button @click="takeHint(3)" :disabled="busy">查看答案（记录使用提示）</button></div><p v-if="hint" class="hint-box">{{hint}}</p><div v-if="feedback" class="feedback" role="status"><strong>{{feedback.feedback || '答案已保存'}}</strong><p>{{feedback.explanation}}</p><p class="muted">证据处理将在后台完成；立即订正不会覆盖首次作答。</p></div></template><div v-else><p class="paper-ref">{{selectedTask.resourceRef || '打开允许的学习资源，完成后回到这里。'}}</p><a v-if="selectedTask.resourceUrl" :href="selectedTask.resourceUrl" target="_blank" rel="noopener noreferrer" class="export-link">打开学习资源 ↗</a></div><div class="hint-actions"><button @click="run(async()=>{await api(`/tasks/${selectedTask!.id}:transition`,{status:'Skipped',reason:'孩子请求跳过'});selectedTask=null;session=null;await refresh()})" v-if="selectedTask.status!=='InProgress'" :disabled="busy">跳过</button><button @click="run(async()=>{await api(`/tasks/${selectedTask!.id}:transition`,{status:'Abandoned',reason:'暂时结束学习'});selectedTask=null;session=null;await refresh()})" :disabled="busy">暂时结束任务</button><button v-if="!isChild" @click="deferTask=selectedTask">安排到另一天</button></div><div v-if="awaitingGrade" class="feedback" role="status"><p>答案已保存。这道题需要家长判分；请家长登录后，到“证据与复习”查看题目并判分。判分后重新打开任务即可完成，无需再次提交。</p><button @click="selectedTask=null;session=null" :disabled="busy">已提交，返回今日任务</button></div><button class="primary" @click="finish" :disabled="busy || !canFinish">{{awaitingGrade?'等待家长判分':'完成这个任务 ✓'}}</button></div>
          <template v-else><div class="today-grid"><section class="hero-card"><p class="eyebrow">{{ activeTask ? '接下来做什么' : '今天的节奏' }}</p><template v-if="activeTask"><div class="task-kind">{{activeTask.type==='Review'?'温故知新':'小练习'}} · {{activeTask.minutes}} 分钟</div><h2>{{activeTask.title}}</h2><p>{{activeTask.reason}}</p><button class="light-button" @click="startTask(activeTask)" :disabled="busy">{{activeTask.status==='InProgress'?'继续学习':'开始学习'}}　→</button></template><template v-else><h2>{{completed?'今天的任务完成了':'今天还没有可开始的任务'}}</h2><p>{{completed?'记得休息，也可以说说今天学会了什么。':'请家长先确认学校进度，并发布今日计划。'}}</p><button v-if="!isChild" class="light-button" @click="navigate('plan')">准备今日计划 →</button></template><span class="hero-decoration">✳</span></section><section class="card progress-card"><p class="eyebrow">今日进度</p><div class="progress-number">{{completed}}<span> / {{view.tasks?.length||0}}</span></div><div class="progress-track"><div :style="{width:`${view.tasks?.length?completed/view.tasks.length*100:0}%`}"></div></div><p>{{view.revision?`${view.revision.budget} 分钟可用 · 预留 ${view.revision.reserved} 分钟`:'一步一步，不着急'}}</p><div v-if="view.revision?.overflow" class="warning">预算超载 {{view.revision.overflow}} 分钟，请家长调整。</div></section></div><section class="task-section"><h2>今天的小步骤 <span>{{view.tasks?.length||0}}</span></h2><div v-for="(t,index) in view.tasks" :key="t.id" class="task-row"><div class="step-number" :class="{done:t.status==='Completed'}">{{t.status==='Completed'?'✓':Number(index)+1}}</div><div class="task-copy"><h3>{{t.title}}<span v-if="t.locked" class="tag">家长安排</span></h3><p>{{t.reason}}</p></div><span class="muted">{{t.minutes}} 分钟</span><button v-if="['Ready','InProgress'].includes(t.status)" @click="startTask(t)" :disabled="busy">{{t.status==='InProgress'?'继续':'开始'}}</button><button v-if="t.status==='Ready'" @click="run(async()=>{await api(`/tasks/${t.id}:transition`,{status:'Skipped',reason:'孩子请求跳过'});await refresh()})" :disabled="busy">跳过</button><span v-else-if="!['Ready','InProgress'].includes(t.status)" class="tag">{{status[t.status]}}</span></div></section></template>
        </template>
        <template v-else-if="page==='plan'">
          <div class="page-heading"><div><p class="eyebrow">PLAN / 学习安排</p><h1>让今天的安排刚刚好</h1><p class="muted">先确认进度，再生成草稿；发布后孩子才能看到。</p></div><input type="date" v-model="date" @change="run(refresh)"></div>
          <div class="two-columns"><section class="card"><h2>今天学校学到哪里</h2><label>课时<select v-model="lessonId" :disabled="busy"><option value="">选择已发布课时</option><optgroup v-for="u in catalog?.units||[]" :label="`第 ${u.sequence} 单元 · ${u.title}`"><option v-for="l in (catalog?.lessons||[]).filter((l:Item)=>l.unitId===u.id)" :value="l.id">{{l.title}}</option></optgroup><optgroup v-for="c in catalog?.courses||[]" :label="`课程 · ${c.title}`"><option v-for="l in (catalog?.lessons||[]).filter((l:Item)=>l.courseId===c.id)" :value="l.id">{{l.title}}</option></optgroup><option v-for="l in (catalog?.lessons||[]).filter((l:Item)=>!l.unitId&&!l.courseId)" :value="l.id">{{l.title}}</option></select></label><button class="primary" :disabled="busy||!lessonId" @click="run(async()=>{await api(`/students/${studentId}/school-progress/${date}/${lessonId}`,{},'PUT');await refresh();notice='学校进度已确认'})">确认今天学到这里</button><p v-if="!catalog" class="muted">先在内容页发布并绑定一个内容版本。</p></section><section class="card"><h2>今日时间预算</h2><div class="inline-fields"><label>总可用分钟<input v-model.number="budget" :disabled="busy" type="number" min="0" max="600"></label><label>列表外作业预留<input v-model.number="reserved" :disabled="busy" type="number" min="0" :max="budget"></label></div><button :disabled="busy" @click="run(async()=>{await api(`/students/${studentId}/availability/${date}`,{minutes:budget,reserved},'PUT');notice='时间预算已保存'})">保存预算</button><p class="muted">如果学校作业已经列为任务，预留应设为 0。</p></section></div>
          <section class="card" v-if="schoolProgress.length || progressChanges.length"><h2>纠正学校进度</h2><p class="muted">选择要纠正的记录，再在上方选择正确课时。这里只影响之后生成的草稿，已发布计划和历史作答保留。</p><div v-if="schoolProgress.length" class="form-grid"><label>要纠正的记录<select v-model="correctionProgressId" :disabled="busy"><option value="">请选择记录</option><option v-for="p in schoolProgress" :value="p.id">{{p.date}} · {{lessonName(p.lessonId)}}</option></select></label><label>更正说明<input v-model="progressReason" maxlength="500" :disabled="busy"></label><div><button @click="correctProgress(lessonId)" :disabled="busy || !correctionProgressId || !lessonId || !progressReason.trim()">按上方所选课时更正</button><button @click="correctProgress(null)" :disabled="busy || !correctionProgressId || !progressReason.trim()">撤回这条记录</button></div></div><details v-if="progressChanges.length"><summary>进度更正记录 · {{progressChanges.length}}</summary><div v-for="c in progressChanges" class="content-editor-row"><p>{{progressDescription(c)}}</p><p class="muted">{{c.reason}}</p></div></details></section>
          <section class="card plan-panel"><div class="section-heading"><h2>计划{{view.revision?` · 第 ${view.revision.number} 版`:''}}</h2><div><button @click="run(refresh)" :disabled="busy">刷新当前计划</button><button @click="generate" :disabled="busy||!catalog">{{view.revision?'重新生成草稿':'生成草稿'}}</button><button v-if="view.revision?.status==='Draft'" class="primary" @click="publishPlan" :disabled="busy">确认并发布</button></div></div><div v-if="view.revision"><p class="muted">{{status[view.revision.status]}} · {{view.revision.budget-view.revision.reserved}} 分钟任务预算</p><div v-for="w in JSON.parse(view.revision.warnings)" class="warning">{{w}}</div><label v-if="view.revision.status==='Draft'">本次计划调整原因<input v-model="planAdjustmentReason" maxlength="1000" placeholder="例如：今天学校作业较多，减少可选练习" :disabled="busy"></label><p v-if="view.revision.status==='Draft'" class="muted">先填写原因，再移动、锁定或移除可选任务。保存只调整草稿；已执行和必做任务保留，锁定任务需先解锁。</p><div v-for="t in view.tasks" class="task-row"><div class="task-copy"><h3>{{t.title}}</h3><p>{{t.reason}} · {{t.minutes}} 分钟</p></div><button v-if="['Ready','InProgress','Deferred'].includes(t.status)" @click="deferTask=t">顺延</button><template v-if="view.revision.status==='Draft'"><button @click="changePlanTasks(t,'up')" aria-label="上移任务" :disabled="busy||!planAdjustmentReason.trim()||view.tasks[0].id===t.id">↑</button><button @click="changePlanTasks(t,'down')" aria-label="下移任务" :disabled="busy||!planAdjustmentReason.trim()||view.tasks[view.tasks.length-1].id===t.id">↓</button><button @click="changePlanTasks(t,'lock')" :disabled="busy||!planAdjustmentReason.trim()">{{t.locked?'解除锁定':'锁定'}}</button><button @click="changePlanTasks(t,'remove')" :disabled="busy||!planAdjustmentReason.trim()||t.mandatory||t.locked||['Completed','InProgress'].includes(t.status)">移除可选任务</button></template><span class="tag">{{status[t.status]}}</span></div><details><summary>未选中候选与原因</summary><pre>{{JSON.parse(view.revision.candidates)}}</pre></details><form v-if="view.revision.status==='Draft'" class="form-grid" @submit.prevent="appendManualTask"><label>任务类型<select v-model="manual.type"><option value="Schoolwork">学校作业</option><option value="Resource">纸笔或讲解活动</option><option value="Practice">正式题目练习</option></select></label><label v-if="manual.type==='Practice'">计划版本题目<select v-model="manual.questionId" required><option :value="null">选择题目</option><option v-for="q in manualQuestions" :value="q.id">{{q.stem}} · {{q.policy==='ObservedSteps'?'家长观察步骤':'练习'}}</option></select></label><label>追加必做任务<input v-model="manual.title" required></label><label>分钟<input v-model.number="manual.minutes" type="number" min="1"></label><label>执行说明<input v-model="manual.resourceRef" required></label><button :disabled="busy">加入草稿</button></form></div><p v-else class="empty">确认课时后，生成今天的学习建议。</p></section>
          <GoalEditor :key="studentId" :student-id="studentId" :goals="goals" :catalog="catalog" @saved="refresh"/>
        </template>
        <template v-else-if="page==='content'">
          <div class="page-heading"><div><p class="eyebrow">CONTENT / 内容发布</p><h1>先审核，再交给孩子</h1><p class="muted">正式版本保留快照，后续修改通过新草稿发布。</p></div><button v-if="can('ContentEditor')" class="primary" @click="run(async()=>{await api('/content/fixture',{});await refresh()})" :disabled="busy">创建混合运算样例</button><button v-if="can('ContentEditor')" @click="run(async()=>{await api('/content/unit-pack',{});await refresh()})" :disabled="busy">准备单元原创题包（待审核）</button></div>
          <button v-if="can('ContentEditor')" @click="run(async()=>{const d=await api('/content/drafts',{title:'我的内容草稿',catalog:{kcs:[],questions:[],resources:[],lessons:[],relations:[]}});await refresh();await loadDraft(d)})" :disabled="busy">新建空白内容草稿</button>
          <div class="warning">20题样例用于开发验证；原创单元题包含160题和15份纸笔资源。教材印次待核对，所有草稿都需要家长审核答案、测量范围和适用性。</div>
          <ContentEditor v-if="draftId" :model-value="editingCatalog" v-model:title="draftTitle" :busy="busy" :published-ids="publishedKCIds" @save="saveDraft" @cancel="draftId=''" />
          <section v-if="can('ContentEditor')" class="card"><h2>草稿与审核</h2><div v-for="d in content.drafts" class="content-row"><div><h3>{{d.title}}</h3><p>{{status[d.status]}} · 版本 {{d.version}}</p></div><label v-if="d.status!=='Published'&&can('Publisher')" style="flex:1 0 100%">审核备注（可选）<input v-model="reviewNotes[d.id]" maxlength="4000" :disabled="busy||!!draftId" placeholder="记录本次答案、能力范围及内容适用性的核对依据"></label><button @click="coverageDraftId=d.id" :disabled="busy||!!draftId">查看待审映射</button><button @click="reviewDraftId=d.id;reviewHistoryVersion++" :disabled="busy">查看审核记录</button><button v-if="d.status!=='Published'" @click="editDraft(d)">编辑</button><button v-if="d.status!=='Published'&&can('Publisher')" :disabled="busy||!!draftId" @click="publishContent(d)">审核答案与映射后发布</button><button v-else :disabled="busy" @click="cloneDraft(d)">创建新修订</button></div><p v-if="!content.drafts.length" class="empty">从样例开始，或在辅助建库中准备来源。</p></section>
          <DraftMappingPreview v-if="coverageDraftId" :key="coverageDraftId+':'+content.drafts.find((d:Item)=>d.id===coverageDraftId)?.version" :draft-id="coverageDraftId" />
          <ContentReviewHistory v-if="reviewDraftId&&can('ContentEditor')" :key="reviewDraftId+':'+reviewHistoryVersion" :draft-id="reviewDraftId" />
          <section class="card"><h2>已发布版本</h2><div v-for="r in content.releases" class="content-row"><div><h3>内容版本 {{r.number}}</h3><p>内容指纹 {{r.hash.slice(0,12)}} · 发布后保持不变</p><details><summary>教材与课程目录</summary><p v-for="b in JSON.parse(r.payload).textbooks||[]">{{b.publisher}} · {{b.grade}} 年级{{b.semester}} · {{b.edition}}</p><p v-for="u in JSON.parse(r.payload).units||[]">第 {{u.sequence}} 单元 · {{u.title}}</p><p v-for="c in JSON.parse(r.payload).courses||[]">{{c.title}} · {{c.provider}}</p></details><details><summary>能力定义与来源</summary><div v-for="k in JSON.parse(r.payload).kcs" class="content-editor-row"><p>{{k.name}}</p><button v-if="can('ContentEditor')" @click="showProvenance(k.id)" :disabled="busy">查看能力来源</button></div></details></div><button v-if="can('ContentEditor')" :disabled="busy" @click="mappingReleaseId=r.id">查看发布映射</button><button v-if="can('Parent')" :disabled="busy||!studentId" @click="bindContent(r.id)">{{student?.activeReleaseId===r.id?'当前学生已绑定':'绑定当前学生'}}</button></div></section>
          <PublishedMappingView v-if="mappingReleaseId&&can('ContentEditor')" :key="mappingReleaseId" :release="content.releases.find((r:Item)=>r.id===mappingReleaseId)!" />
          <KnowledgeChanges v-if="can('ContentEditor')" :releases="content.releases" :publisher="can('Publisher')" :disabled="busy" />
          <MappingWorkbench v-if="can('ContentEditor')" :drafts="content.drafts" :releases="content.releases" :disabled="busy||!!draftId" @refresh="run(refresh)" @edit-draft="id=>{const d=content.drafts.find((d:Item)=>d.id===id);if(d)editDraft(d)}" />
        </template>
        <template v-else-if="page==='assessment'">
          <div class="page-heading"><div><p class="eyebrow">EVIDENCE / 学习依据</p><h1>看见进步，也看见缺口</h1><p class="muted">掌握状态是安排学习的线索；每条贡献都能回溯。</p></div><button @click="run(refresh)" :disabled="busy">刷新后台结果</button></div>
          <p v-if="evidencePending" class="warning" role="status">还有 {{evidencePending}} 条结果正在后台处理，页面会短暂等待并自动刷新；持续未完成时请查看后台或手动刷新。</p><section v-if="detail" class="card"><button class="text-button" @click="detail=null">收起详情</button><h2>证据明细</h2><p>模型估计 {{detail.mastery?(detail.mastery.probability*100).toFixed(1):50}}% · 不代表考试正确率</p><pre>{{detail.mastery?.gaps}}</pre><div v-for="e in detail.evidence" class="evidence-row"><strong>{{e.positive?'正':'负'}}证据 {{e.weight}}</strong><span>{{new Date(e.occurredAt).toLocaleString('zh-CN')}}</span><details><summary>权重与版本</summary><pre>{{JSON.parse(e.factors)}}</pre><p>发布版本 {{e.releaseId}}</p><p>作答 {{e.attemptId}}</p></details></div></section>
          <section class="card"><h2>知识点状态</h2><div v-for="m in masteries" class="content-row"><div><h3>{{catalog?.kcs.find((k:Item)=>k.id===m.kcId)?.name || '历史知识点'}} · {{status[m.status]}} <span v-if="m.needsRecheck" class="tag">需复核</span></h3><p>有效证据 {{m.effectiveEvidence.toFixed(2)}} · {{m.distinctQuestions}} 道不同题 · {{m.confidence}} 覆盖级别</p></div><button @click="run(async()=>{detail=await api(`/students/${studentId}/mastery/${m.kcId}`)})">查看依据</button></div><p v-if="!masteries.length" class="empty">还没有可用证据。完成任务或看资源不会直接改变掌握状态。</p></section>
          <section class="card"><h2>错题与复测</h2><div v-for="r in reviews" class="content-row"><div><h3>{{r.targetType==='WrongQuestion'?'错题复习':'知识点复测'}} · {{r.stage}}</h3><p>到期 {{r.dueDate}} · {{status[r.status]}} · 错误类型 {{r.errorType}}</p></div><span class="tag">{{r.wrongCount}} 次独立错误</span></div><p v-if="!reviews.length" class="empty">目前没有复习日程。</p></section>
          <PaperReview v-if="reviewingPaper" :key="reviewingPaper.id" :wrong="reviewingPaper" :releases="content.releases" @saved="refresh" @close="reviewingPaper=null" @edit-draft="id=>openCandidateDraft({createdDraftId:id})"/><section v-if="gradingContext" class="card"><h2>核对题目与观察步骤</h2><p>{{gradingContext.question.stem}}</p><p>参考答案：{{gradingContext.question.answer}}</p><p>{{gradingContext.question.explanation}}</p><p>孩子答案：{{gradingContext.attempt.answer}}</p><p class="muted">{{gradingContext.notice}}</p><form @submit.prevent="previewObservedGrade"><label>整题判分<select v-model="gradingForm.result"><option value="Correct">正确</option><option value="Incorrect">错误</option><option value="Partial">部分正确</option><option value="Unscorable">不可评分</option></select></label><div v-for="s in gradingForm.steps" class="form-grid"><label>{{s.step}} · {{s.kcName}}<select v-model="s.result"><option value="Unknown">未知 / 未观察</option><option value="Correct">观察到正确</option><option value="Incorrect">观察到错误</option></select></label><label>该步骤提示程度<select v-model.number="s.hintLevel"><option :value="0">独立完成</option><option :value="1">轻提示</option><option :value="2">步骤提示</option><option :value="3">已展示答案</option></select></label></div><label>判分依据<textarea v-model="gradingForm.reason" required></textarea></label><button :disabled="busy">预览判分影响</button><button type="button" @click="gradingContext=null;gradingPreview=null">取消判分</button></form></section><section v-if="gradingPreview" class="card"><h2>判分影响预览</h2><p>{{status[gradingPreview.before]}} → {{status[gradingPreview.after]}}</p><p>{{gradingPreview.input.reason}}</p><p v-for="s in gradingPreview.input.steps">{{s.step}}：{{s.result==='Unknown'?'未知 / 未观察':status[s.result]}} · {{s.hintLevel===0?'独立完成':s.hintLevel===1?'轻提示':s.hintLevel===2?'步骤提示':'已展示答案'}}</p><p>将重放 {{gradingPreview.replayAttempts}} 次作答。{{gradingPreview.notice}}</p><button class="primary" @click="confirmGrade" :disabled="busy">确认更正并重算</button><button @click="gradingPreview=null">取消</button></section><section class="card"><h2>历史映射更正</h2><p class="muted">仅使用已审核发布的新映射；原题干与原答案不变，先预览影响再确认。</p><label>首次作答<select v-model="mappingAttempt"><option value="">选择作答</option><option v-for="a in attempts.attempts.filter((x:Item)=>x.number===1)" :value="a.id">{{a.answer}} · {{new Date(a.createdAt).toLocaleString('zh-CN')}}</option></select></label><label>修正映射所在版本<select v-model="mappingRelease"><option value="">选择正式版本</option><option v-for="r in content.releases" :value="r.id">内容版本 {{r.number}}</option></select></label><button @click="previewMapping" :disabled="busy||!mappingRelease||!mappingAttempt">预览归因变化</button><div v-if="mappingPreview" class="warning"><p>{{mappingPreview.notice}}</p><p>影响 {{mappingPreview.changes.length}} 条首次作答，旧世代保留。</p><button @click="confirmMapping" :disabled="busy">确认更正并重放</button><button @click="mappingPreview=null">取消</button></div></section><section class="card"><h2>登记纸质错题</h2><form @submit.prevent="run(async()=>{await api(`/students/${studentId}/paper-wrongs`,paper);paper={stem:'',answer:'',fileId:null,errorType:'Unknown'};await refresh();notice='已登记，尚未审核归因，不产生掌握证据'})"><label>错题图片<input type="file" accept="image/png,image/jpeg" @change="upload($event,false)"></label><label>题干（可稍后补充）<textarea v-model="paper.stem" rows="3"></textarea></label><label>孩子答案<input v-model="paper.answer"></label><button :disabled="busy || (!paper.stem&&!paper.fileId)">保存为待校正错题</button></form><div v-for="w in paperWrongs" class="content-row"><div><h3>{{w.stem || '图片错题'}}</h3><p>{{w.status==='Confirmed'?'原题与结果已确认 · 历史记录保留':w.draftId?'原题草稿待审核发布':'待审核归因 · 仅登记不会判断能力'}}</p><img v-if="w.fileId" :src="`/api/v1/files/${w.fileId}`" style="max-width:200px;max-height:160px" alt="私有错题图片"></div><button v-if="w.status!=='Confirmed'" @click="reviewingPaper=w">补齐并审核归因</button><button v-else @click="openGrading(w.attemptId)">查看代录判分</button></div></section><section class="card"><h2>家长判分与更正</h2><div v-for="a in attempts.attempts" class="content-row"><div><h3>作答：{{a.answer}}</h3><p>第 {{a.number}} 次 · {{status[attempts.gradings.filter((g:Item)=>g.attemptId===a.id).at(-1)?.result]}}</p></div><button @click="openGrading(a.id)" :disabled="busy">查看题目并判分</button></div></section>
        </template>
        <template v-else-if="page==='report'">
          <WeeklyOverview :summary="summary" :busy="busy" :time-zone="student?.timeZone||'Asia/Shanghai'" @select="value=>run(async()=>{reportEnd=value;await refresh()})"/><ParentBurden v-if="summary&&studentId" :key="studentId" :student-id="studentId" :time-zone="student?.timeZone||'Asia/Shanghai'" :burden="summary.parentBurden" @saved="run(refresh)"/><section class="card"><h2>下一周的起点</h2><p>先确认学校进度，优先处理到期复习。请持续记录实际使用、到期复习与家长投入。四周家庭试用尚未验收，单周记录不能代表长期学习效果。</p></section>
        </template>
        <template v-else-if="page==='builder'">
          <div class="page-heading"><div><p class="eyebrow">BUILDER / 辅助建库</p><h1>从来源到可审核的候选</h1><p class="muted">{{builder.provider}}。接受候选生成草稿，仍需补充题目并正式发布。</p></div><button @click="run(refresh)">刷新</button></div>
          <section class="card"><h2>导入文本型 PDF</h2><label>选择私有来源文件<input type="file" accept="application/pdf" @change="upload($event,true)" :disabled="busy"></label><p class="muted">最多 10 MB、200 页。扫描件若无文本层会提示需要 OCR；全部在本地解析。</p></section><section class="card"><h2>导入受控文本</h2><form @submit.prevent="run(async()=>{await api('/content/sources',source);await refresh();notice='来源已导入并分段'})"><label>来源标题<input v-model="source.title" required></label><label>文本内容<textarea v-model="source.text" rows="5" required placeholder="每段一个可供审核的能力描述，注明来源。"></textarea></label><p class="muted">当前只本地处理；不向外部模型发送内容。</p><button class="primary" :disabled="busy">保存来源</button></form></section>
          <section class="card"><h2>来源与运行</h2><div v-for="s in builder.sources" class="content-row"><div><h3>{{s.title}}</h3><p>{{s.usageScope}} · 指纹 {{s.hash.slice(0,12)}}</p></div><button :disabled="busy" @click="run(async()=>{await api('/builder/runs',{sourceId:s.id,provider:'Mock'});await refresh()})">验证候选流程</button></div><p v-for="r in builder.runs" class="muted">{{r.provider}} / {{r.model}} · {{status[r.status] || r.status}} · {{r.inputVersion==='builder-input/2'?(r.libraryReleaseId?`参考内容第 ${builder.libraries?.find((l:Item)=>l.id===r.libraryReleaseId)?.number} 版`:'生成时没有正式内容库'):'历史输入版本未记录，需重新运行'}}</p></section>
          <section class="card"><h2>逐项审核</h2><div v-for="c in builder.candidates" class="candidate"><span class="tag">{{status[c.status]}}</span><label>{{c.status==='Pending'?'名称':'原始候选名称'}}<input v-model="c.name" :disabled="c.status!=='Pending'"></label><blockquote>{{c.quote}}</blockquote><p class="muted">{{builder.chunks.find((x:Item)=>x.id===c.chunkId)?.locator}} · 来自真实输入片段</p><label>{{c.status==='Pending'?'可测行为':'原始候选行为'}}<input v-model="c.behavior" :disabled="c.status!=='Pending'"></label><label>{{c.status==='Pending'?'能力边界':'原始候选边界'}}<input v-model="c.boundary" :disabled="c.status!=='Pending'"></label><details><summary>相近能力（模拟检索，仅供审核排序）</summary><div v-for="match in JSON.parse(c.matches)" class="content-row"><div><h3>{{match.name}}</h3><p>{{match.behavior}}<br>{{match.boundary}}</p></div><button v-if="c.status==='Pending'" :disabled="busy" @click="run(async()=>{await api(`/builder/candidates/${c.id}:decide`,{decision:'LinkExisting',reason:'家长确认与已有能力相同',existingKCId:match.kcId,name:c.name});await refresh()})">关联已有能力</button></div></details><div v-if="c.createdDraftId"><button @click="openCandidateDraft(c)" :disabled="busy">继续编辑审核草稿</button><button @click="showProvenance(c.createdKCId)" :disabled="busy">查看引用与审核</button></div><p v-if="c.reviewReason" class="muted">审核依据：{{c.reviewReason}}</p><div v-if="c.status==='Pending'"><button @click="decide(c,'CreateDraft')" :disabled="busy">接受为新草稿</button><button @click="decide(c,'Reject')" :disabled="busy">拒绝</button></div></div></section>
          <BuilderRuns :runs="builder.runs||[]" :attempts="builder.attempts||[]" :sources="builder.sources||[]" :libraries="builder.libraries||[]" :disabled="busy" @refresh="run(refresh)" />
        </template>
        <template v-else-if="page==='settings'">
          <div class="page-heading"><div><p class="eyebrow">FAMILY / 家庭设置</p><h1>按照孩子的节奏</h1></div></div><section class="card"><h2>添加学生</h2><form class="form-grid" @submit.prevent="createStudent"><label>昵称<input v-model="newStudent.name" required></label><label>年级<input v-model.number="newStudent.grade" type="number" min="1" max="12"></label><label>每日学习分钟<input v-model.number="newStudent.dailyMinutes" type="number" min="0" max="600"></label><button class="primary" :disabled="busy">创建</button></form></section><section v-if="studentId" class="card"><h2>备份你的学习记录</h2><p>下载当前学生的进度、计划、历史作答、证据和日程。</p><a :href="`/api/v1/students/${studentId}/export`" class="export-link">下载学习数据</a><p class="muted">完整数据库加密备份与恢复操作见项目运行手册。</p></section><section v-if="studentId" class="card"><h2>学生数据控制</h2><button @click="run(async()=>{deletePreview=await api(`/students/${studentId}/delete-preview`)})" :disabled="busy">预览删除当前学生</button><div v-if="deletePreview" class="warning"><p>将永久删除 {{deletePreview.student}} 及 {{deletePreview.attempts}} 次作答和相关数据。删除不可从普通界面撤销。</p><label>家长密码<input type="password" v-model="deletePassword" autocomplete="current-password"></label><label>输入“永久删除学生”<input v-model="deleteConfirm"></label><button @click="run(async()=>{await api(`/students/${studentId}:delete`,{previewHash:deletePreview!.previewHash,password:deletePassword,confirm:deleteConfirm});deletePassword='';deleteConfirm='';deletePreview=null;await loadIdentity();notice='学生数据已删除'})" :disabled="busy || deleteConfirm!=='永久删除学生' || !deletePassword">确认永久删除</button><button @click="deletePreview=null;deletePassword='';deleteConfirm=''">取消</button></div></section><FamilySettings :owner="me.family.ownerAccountId===me.actor.accountId" :owner-id="me.family.ownerAccountId"/><section class="card"><h2>运行范围</h2><p>本地私有运行。外部模型暂未接入。当前内容为混合运算原创样例，教材具体印次与教材原题需要补充后审核。</p></section>
        </template>
      </template>
      <section v-if="deferTask" class="card"><h2>顺延：{{deferTask.title}}</h2><label>目标日期<input type="date" v-model="deferDate"></label><label>原因<input v-model="deferReason" placeholder="例如今天时间不足"></label><button @click="defer" :disabled="busy||!deferReason">移至目标日草稿</button><button @click="deferTask=null">取消</button></section><section v-if="provenance" class="card" aria-label="内容来源追溯"><h2>引用与审核记录</h2><p class="muted">{{provenance.notice}}</p><div v-for="p in provenance.citations" class="content-editor-row"><h3>{{p.source.title}}</h3><p>{{p.citation.locator}} · {{p.source.usageScope}}</p><blockquote>{{p.citation.quote}}</blockquote><p>审核依据：{{p.review.reviewReason || '历史审核理由未记录'}}</p><p class="muted">{{p.run.provider}} / {{p.run.model}} · {{p.run.inputVersion}}</p><a v-if="p.source.fileId" :href="`/api/v1/files/${p.source.fileId}`">下载原始私有来源</a></div><button @click="provenance=null">关闭记录</button></section>
      <footer v-if="me" class="main-foot">小步 · 学习是日常的积累 <span>已发布内容才参与正式学习</span></footer>
    </main>
  </div>
</template>
